import{_ as s,o as a,c as t,ag as o}from"./chunks/framework.D2veAa-g.js";const p=JSON.parse('{"title":"信息安全的抗攻击技术","description":"","frontmatter":{"title":"信息安全的抗攻击技术"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/信息安全技术基础知识（第二版）/信息安全的抗攻击技术.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/信息安全技术基础知识（第二版）/信息安全的抗攻击技术.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/信息安全技术基础知识（第二版）/信息安全的抗攻击技术.md"};function n(r,l,e,c,u,d){return a(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="信息安全的抗攻击技术" tabindex="-1">信息安全的抗攻击技术 <a class="header-anchor" href="#信息安全的抗攻击技术" aria-label="Permalink to &quot;信息安全的抗攻击技术&quot;">​</a></h1><blockquote><p>共 10 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-ddos攻击主要破坏信息安全的-要素。" tabindex="-1">Q1. DDoS攻击主要破坏信息安全的 （ ） 要素。 <a class="header-anchor" href="#q1-ddos攻击主要破坏信息安全的-要素。" aria-label="Permalink to &quot;Q1. DDoS攻击主要破坏信息安全的 （ ） 要素。&quot;">​</a></h2><ul><li><strong>A.</strong> 机密性</li><li><strong>B.</strong> 完整性</li><li><strong>C.</strong> 可用性</li><li><strong>D.</strong> 可控性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q2-在tcp三次握手过程中-syn-flood攻击的主要原理是" tabindex="-1">Q2. 在TCP三次握手过程中，SYN Flood攻击的主要原理是（） <a class="header-anchor" href="#q2-在tcp三次握手过程中-syn-flood攻击的主要原理是" aria-label="Permalink to &quot;Q2. 在TCP三次握手过程中，SYN Flood攻击的主要原理是（）&quot;">​</a></h2><ul><li><strong>A.</strong> 攻击者发送大量伪造源地址的SYN报文，使目标主机的半连接队列被填满</li><li><strong>B.</strong> 攻击者截获正常的ACK报文，阻止TCP连接的正常建立</li><li><strong>C.</strong> 攻击者发送大量RST报文，强制断开已建立的TCP连接</li><li><strong>D.</strong> 攻击者伪造FIN报文，欺骗目标主机提前关闭TCP连接</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q3-在局域网环境中-arp欺骗攻击的主要原理是-。" tabindex="-1">Q3. 在局域网环境中，ARP欺骗攻击的主要原理是（）。 <a class="header-anchor" href="#q3-在局域网环境中-arp欺骗攻击的主要原理是-。" aria-label="Permalink to &quot;Q3. 在局域网环境中，ARP欺骗攻击的主要原理是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 通过伪造网关的MAC地址，使局域网内的PC错误识别网关，导致网络通信异常</li><li><strong>B.</strong> 通过修改DNS服务器配置，将域名解析重定向到攻击者控制的IP地址</li><li><strong>C.</strong> 通过发送大量TCP SYN请求包，消耗目标服务器的连接资源</li><li><strong>D.</strong> 通过伪造IP数据包的源地址，隐藏攻击者的真实身份</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q4-dns欺骗攻击的主要实现方式是-。" tabindex="-1">Q4. DNS欺骗攻击的主要实现方式是（）。 <a class="header-anchor" href="#q4-dns欺骗攻击的主要实现方式是-。" aria-label="Permalink to &quot;Q4. DNS欺骗攻击的主要实现方式是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 通过冒充域名服务器，将查询的IP地址设为攻击者的IP地址</li><li><strong>B.</strong> 通过修改路由表，将数据包重定向到攻击者控制的服务器</li><li><strong>C.</strong> 通过伪造MAC地址，欺骗局域网内的网关设备</li><li><strong>D.</strong> 通过发送大量请求包，消耗目标DNS服务器的系统资源</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q5-在端口扫描技术中-扫描主机向目标计算机发送syn数据段请求建立连接-如果目标端口活动则回应syn-1、ack-1-扫描主机随即发送rst拒绝连接。这种扫描方式是-。" tabindex="-1">Q5. 在端口扫描技术中，扫描主机向目标计算机发送SYN数据段请求建立连接，如果目标端口活动则回应SYN=1、ACK=1，扫描主机随即发送RST拒绝连接。这种扫描方式是（）。 <a class="header-anchor" href="#q5-在端口扫描技术中-扫描主机向目标计算机发送syn数据段请求建立连接-如果目标端口活动则回应syn-1、ack-1-扫描主机随即发送rst拒绝连接。这种扫描方式是-。" aria-label="Permalink to &quot;Q5. 在端口扫描技术中，扫描主机向目标计算机发送SYN数据段请求建立连接，如果目标端口活动则回应SYN=1、ACK=1，扫描主机随即发送RST拒绝连接。这种扫描方式是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 全TCP连接扫描</li><li><strong>B.</strong> 半打开式扫描（SYN扫描）</li><li><strong>C.</strong> FIN扫描</li><li><strong>D.</strong> 第三方扫描</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q6-在分布式拒绝服务攻击-ddos-的三级控制结构中-负责接收主控端命令并对目标实施实际攻击的组件是-。" tabindex="-1">Q6. 在分布式拒绝服务攻击（DDoS）的三级控制结构中，负责接收主控端命令并对目标实施实际攻击的组件是（）。 <a class="header-anchor" href="#q6-在分布式拒绝服务攻击-ddos-的三级控制结构中-负责接收主控端命令并对目标实施实际攻击的组件是-。" aria-label="Permalink to &quot;Q6. 在分布式拒绝服务攻击（DDoS）的三级控制结构中，负责接收主控端命令并对目标实施实际攻击的组件是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> Client（客户端）</li><li><strong>B.</strong> Handler（主控端）</li><li><strong>C.</strong> Agent（代理端）</li><li><strong>D.</strong> Server（服务端）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-拒绝服务攻击-dos-的主要攻击目标是-。" tabindex="-1">Q7. 拒绝服务攻击（DoS）的主要攻击目标是（）。 <a class="header-anchor" href="#q7-拒绝服务攻击-dos-的主要攻击目标是-。" aria-label="Permalink to &quot;Q7. 拒绝服务攻击（DoS）的主要攻击目标是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 窃取系统中的敏感数据</li><li><strong>B.</strong> 使系统资源耗尽或服务中断</li><li><strong>C.</strong> 获取系统管理员权限</li><li><strong>D.</strong> 篡改系统配置文件内容</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q8-在拒绝服务攻击-dos-的主要分类中-下列哪一项不属于常见的攻击模式-。" tabindex="-1">Q8. 在拒绝服务攻击（DoS）的主要分类中，下列哪一项不属于常见的攻击模式（ ）。 <a class="header-anchor" href="#q8-在拒绝服务攻击-dos-的主要分类中-下列哪一项不属于常见的攻击模式-。" aria-label="Permalink to &quot;Q8. 在拒绝服务攻击（DoS）的主要分类中，下列哪一项不属于常见的攻击模式（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 消耗系统资源</li><li><strong>B.</strong> 破坏或更改配置信息</li><li><strong>C.</strong> 物理破坏或改变网络部件</li><li><strong>D.</strong> 加密系统数据</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q9-在网络安全领域中-以下哪种欺骗攻击方式通过冒充域名服务器-将查询的ip地址设为攻击者的ip地址从而使用户访问到攻击者的网站而非真实目标网站-。" tabindex="-1">Q9. 在网络安全领域中，以下哪种欺骗攻击方式通过冒充域名服务器，将查询的IP地址设为攻击者的IP地址从而使用户访问到攻击者的网站而非真实目标网站（ ）。 <a class="header-anchor" href="#q9-在网络安全领域中-以下哪种欺骗攻击方式通过冒充域名服务器-将查询的ip地址设为攻击者的ip地址从而使用户访问到攻击者的网站而非真实目标网站-。" aria-label="Permalink to &quot;Q9. 在网络安全领域中，以下哪种欺骗攻击方式通过冒充域名服务器，将查询的IP地址设为攻击者的IP地址从而使用户访问到攻击者的网站而非真实目标网站（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> ARP欺骗</li><li><strong>B.</strong> DNS欺骗</li><li><strong>C.</strong> IP欺骗</li><li><strong>D.</strong> SYN欺骗</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q10-关于系统漏洞扫描的分类-以下说法正确的是-。" tabindex="-1">Q10. 关于系统漏洞扫描的分类，以下说法正确的是（ ）。 <a class="header-anchor" href="#q10-关于系统漏洞扫描的分类-以下说法正确的是-。" aria-label="Permalink to &quot;Q10. 关于系统漏洞扫描的分类，以下说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 基于网络的扫描需要在目标系统上安装代理或服务</li><li><strong>B.</strong> 基于主机的扫描不需要涉及目标系统的管理员</li><li><strong>C.</strong> 基于网络的扫描可以扫描更多的漏洞</li><li><strong>D.</strong> 基于主机的扫描具有网络流量负载小的优点</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details>',32)])])}const m=s(i,[["render",n]]);export{p as __pageData,m as default};
